import{e as t,ab as a,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [June]","description":"June 2026 updates","frontmatter":{"title":"Monthly Updates [June]","description":"June 2026 updates","date":"2026-06-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/june-2026.md","filePath":"posts/june-2026.md"}'),l={name:"posts/june-2026.md"};function h(d,e,p,f,g,m){const r=a("Post");return o(),n("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added a new backup site <strong><a href="https://fmhy.net/other/backups" target="_blank" rel="noreferrer">FMHY X</a></strong> that has a bunch of new and experimental <a href="https://i.ibb.co/HL1cq43H/image.png" target="_blank" rel="noreferrer">features</a> / <a href="https://i.imgur.com/3kPD77T.png" target="_blank" rel="noreferrer">2</a> like live link status&#39;, a private mode, one-click proxy mode, and more, ty to both @WilkinsCoffeeArchives + @Zenith for making this.</p></li><li><p>Added a <strong><a href="https://fmhy.net/recently-removed" target="_blank" rel="noreferrer">Recently Removed</a></strong> page to our site, this will track the last 30 days of removals + links to the GitHub changes themselves, ty to @bread for doing this.</p></li><li><p>Updated search engine to show more relevant results, give suggestions if nothing is found, save last 20 searches, and added a &quot;show more results&quot; option, ty to @bread for doing this. <a href="https://i.ibb.co/FkZfdmDP/image.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/PV8HGwv.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added <a href="https://i.imgur.com/prj36Pm.mp4" target="_blank" rel="noreferrer">Search Scroll to Match</a>, search results will now take you directly to selected result, rather than just the section head, ty to both @bread + @none of your business for doing this.</p></li><li><p>Added <a href="https://i.imgur.com/Ms1B7zI.mp4" target="_blank" rel="noreferrer">Active TOC Highlighting</a> support for smaller screens, ty to @bread for doing this.</p></li><li><p>Added section for <a href="https://fmhy.net/gaming#pokemon" target="_blank" rel="noreferrer">Pokémon Games</a> under Browser Games.</p></li><li><p>Added section for <a href="https://fmhy.net/educational#go-baduk-weiqi" target="_blank" rel="noreferrer">Go / Baduk / Weiqi</a> under Hobbies, ty to @Dan for <a href="https://i.ibb.co/99TPQZMn/image.png" target="_blank" rel="noreferrer">doing this</a> / <a href="https://i.imgur.com/APqaeez.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Added sections for <a href="https://fmhy.net/misc#fashion-clothing" target="_blank" rel="noreferrer">Fashion / Clothing</a> + <a href="https://fmhy.net/misc#sports" target="_blank" rel="noreferrer">Sports</a> under Misc.</p></li><li><p>Added section for <a href="https://fmhy.net/educational#economics" target="_blank" rel="noreferrer">Economics</a> under Edu &gt; Humanities.</p></li><li><p>Merged all <a href="https://fmhy.net/internet-tools#password-managers" target="_blank" rel="noreferrer">Password Managers</a> into one section, and added platform icons for each, ty to @nug for doing this. <a href="https://i.ibb.co/qYLDsNjb/Before-After-Video-Editors.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/wZnPpCk.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added Platform Icons + cleaned up <a href="https://fmhy.net/video-tools#video-editors" target="_blank" rel="noreferrer">Video Editors</a> section, ty to @wispy for doing this. <a href="https://i.ibb.co/wZ3q52Pz/Before-After-Video-Editors.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/0Rt6W8Z.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added platform icons to both <a href="https://fmhy.net/gaming-tools#launchers" target="_blank" rel="noreferrer">Minecraft Launcher</a> sections. <a href="https://i.ibb.co/JRWxjLtk/123123123.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/Ejm9AHr.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Added Platform Icons to the <a href="https://fmhy.net/text-tools#text-editors" target="_blank" rel="noreferrer">Text Editors</a> section, ty to @litekin for doing this. <a href="https://i.ibb.co/vCRP3yww/34253453.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/O7meW3S.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Disabled the transparency effect on sites drop down menu to make them easier to read, ty to @Zenith for doing this. <a href="https://i.ibb.co/dwJnyw1V/image.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/EDoUOD6.png" target="_blank" rel="noreferrer">2</a></p></li><li><p>Made single page markdown accessible on <a href="https://fmhy.net/single-page.md" target="_blank" rel="noreferrer">site itself</a> rather than just API page, should be faster now, ty to @bread for doing this.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/gaming-tools#gaming-tools" target="_blank" rel="noreferrer">r/CrackWatch</a> in Gaming Tools, popular and useful piracy game release tracking group.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#download-games" target="_blank" rel="noreferrer">HizSearch</a> in Game Download, multi-site game download search engine, uses trusted sources, has a nice UI, and active development.</p></li><li><p>Starred <a href="https://fmhy.net/educational#astronomy" target="_blank" rel="noreferrer">NASA2Explore</a> in Astronomy section, the official source of all NASA images, including full metadata.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#youtube-tools" target="_blank" rel="noreferrer">LocalTube Manager</a> in YouTube Tools, extension that allows you to use YouTubes features without an account, including subscribing, playlists, and notifications, also allows you to export data to sync across devices.</p></li><li><p>Starred <a href="https://fmhy.net/developer-tools#coding-agents-extensions" target="_blank" rel="noreferrer">OpenCode</a> in AI Coding Agents, has good free models + seems to work well for people.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#browser-emulators" target="_blank" rel="noreferrer">DOS Zone</a> in Browser Emulators, retro PC browser emulator that works well + has a big library.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-device" target="_blank" rel="noreferrer">Shizuku Fork</a> in Android Device, fixes multiple features, adds QoL updates, and is maintained well.</p></li><li><p>Starred ⁠<a href="https://fmhy.net/gaming-tools#steam-epic" target="_blank" rel="noreferrer">SteaMidra</a> in Steam Tools, multi-tool that includes DLC unlockers, multiplayer fixes, and a manifest tool.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-rss-readers" target="_blank" rel="noreferrer">ReadYou</a> in Android RSS Readers, clean design, offline support, Google Reader + Fever API sync</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-utilities" target="_blank" rel="noreferrer">Gadgetbridge</a> in Android Utilities, open-source gadget manager w/ support for 300+ devices and no account required.</p></li><li><p>Starred <a href="https://fmhy.net/video#android-tv-firestick" target="_blank" rel="noreferrer">SmartTube</a> in Android TV, works on lots of TVs, has improved navigation, and is preferred over TizenTube by some.</p></li><li><p>Starred <a href="https://fmhy.net/educational#chess" target="_blank" rel="noreferrer">Lucas Chess + Chess Tempo</a> in Educational Chess section. Feature-rich chess learning platforms both of which seem to be well liked and good for beginners.</p></li><li><p>Starred <a href="https://fmhy.net/misc#maps" target="_blank" rel="noreferrer">nakarte</a> in Maps section, world map with multiple layers and street views all combined into one.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#strategy" target="_blank" rel="noreferrer">OpenFront</a> in Browser Strategy Games, open-source Conquest / War style game with active multiplayer community.</p></li><li><p>Starred <a href="https://fmhy.net/audio#concerts-live-shows" target="_blank" rel="noreferrer">setlist.fm</a> in Concerts / Live section, in-depth database of setlists for almost every concert and tour in history.</p></li><li><p>Starred <a href="https://fmhy.net/misc#assistance-charity" target="_blank" rel="noreferrer">GiveWell</a> in Charity / Donations section, charity research group, publishes their research process online, and charges no fees.</p></li><li><p>Added <a href="https://fmhy.net/audio#spotify-tools" target="_blank" rel="noreferrer">Spicy Lyrics</a> next to Spicetify. Improved lyrics with very nice UI, not technically a star, but people seem to really like it so it felt worth mentioning.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed AnimeKai (and yflix) as their <a href="https://i.ibb.co/PG1hTsLr/image.png" target="_blank" rel="noreferrer">datacenter caught fire</a> / <a href="https://i.imgur.com/IbmnBHC.png" target="_blank" rel="noreferrer">2</a> and they&#39;re no longer able to continue the projects.</p></li><li><p>Removed ⁠Fluxy Repacks as they&#39;re <a href="https://i.ibb.co/s8YxT58/image.png" target="_blank" rel="noreferrer">shutting down</a> / <a href="https://i.imgur.com/qNrK4g8.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Removed AnimeTosho as they&#39;re shutting down.</p></li><li><p>Added <a href="https://www.reddit.com/r/gachagaming/comments/1tcrr3p/ldplayer_ldshop_expose_user_data/" target="_blank" rel="noreferrer">LD Cloud / LDPlayer / LD Shop</a> / <a href="https://x.com/NTE_WL/status/2054627592054153273" target="_blank" rel="noreferrer">2</a> to Unsafe List as they seem to of been caught logging peoples keystrokes on payment screens.</p></li></ul>',9))])}const b=t(l,[["render",h]]);export{u as __pageData,b as default};
